begin;
do $$
declare actor uuid; regular_actor uuid; a integer; b integer; foreign_id integer; gid bigint; version timestamptz; result jsonb; rejected boolean; res_id bigint;
  company text:='__TEST_GRUPOS_ROLLBACK__'; hoy date:=(now() at time zone 'America/Santiago')::date;
begin
  select auth_user_id into actor from public.usuarios where empresa='Obraxis' and lower(coalesce(rol_base,rol,'')) in ('superusuario','superadmin') and auth_user_id is not null limit 1;
  if actor is null then raise exception 'Falta actor para prueba'; end if;
  perform set_config('request.jwt.claim.sub',actor::text,true);
  insert into public.obras(empresa,nombre) values(company,'Obra grupo A'),(company,'Obra grupo B');
  insert into public.inventario_maquinaria(empresa,tipo,patente,estado_equipo) values(company,'Excavadora','TEST-A','Operativo') returning id into a;
  insert into public.inventario_maquinaria(empresa,tipo,patente,estado_equipo) values(company,'Compresor','TEST-B','Operativo') returning id into b;
  insert into public.inventario_maquinaria(empresa,tipo,patente) values('__TEST_OTRA_GRUPOS__','Otro','TEST-C') returning id into foreign_id;
  result:=public.gestionar_grupo_equipos(company,'crear',null,'Conjunto mixto','Prueba',array[a,b,a]);gid:=(result->>'id')::bigint;
  if (select count(*) from public.maquinaria_grupos_equipos where grupo_id=gid)<>2 then raise exception 'Miembros repetidos'; end if;
  if exists(select 1 from public.inventario_maquinaria where id in(a,b) and obra_nombre is not null) then raise exception 'Crear grupo movió equipos'; end if;
  select actualizado_en into version from public.maquinaria_grupos where id=gid;
  rejected:=false;begin perform public.gestionar_grupo_equipos(company,'editar',gid,'Inválido','',array[a,foreign_id],version);exception when others then rejected:=true;end;
  if not rejected or (select count(*) from public.maquinaria_grupos_equipos where grupo_id=gid)<>2 then raise exception 'Aceptó equipo ajeno o dejó edición parcial'; end if;
  rejected:=false;begin perform public.gestionar_grupo_equipos(company,'crear',null,' CONJUNTO MIXTO ','',array[a]);exception when others then rejected:=true;end;
  if not rejected then raise exception 'Aceptó nombre duplicado'; end if;
  insert into public.maquinaria_reservas(empresa,equipo_id,fecha_inicio,fecha_fin,estado) values(company,b::text,hoy,hoy+5,'Pendiente') returning id into res_id;
  rejected:=false;begin perform public.asignar_grupo_equipos(company,gid,version,array[a,b],'Obra grupo A',hoy,hoy+5,false);exception when others then rejected:=true;end;
  if not rejected or exists(select 1 from public.inventario_maquinaria where id in(a,b) and obra_nombre is not null) then raise exception 'Ignoró reserva o guardó parcialmente'; end if;
  delete from public.maquinaria_reservas where id=res_id;
  update public.inventario_maquinaria set estado_equipo='En Mantención' where id=b;
  rejected:=false;begin perform public.asignar_grupo_equipos(company,gid,version,array[a,b],'Obra grupo A',hoy,hoy+5,false);exception when others then rejected:=true;end;
  if not rejected or exists(select 1 from public.inventario_maquinaria where id in(a,b) and obra_nombre is not null) then raise exception 'Ignoró estado operacional'; end if;
  update public.inventario_maquinaria set estado_equipo='Operativo' where id=b;
  insert into public.maquinaria_arriendos(id,empresa,equipo_id,equipo_tipo,empresa_arrendataria,fecha_inicio,fecha_fin) values(-b,company,b,'Compresor','Tercero prueba',hoy,hoy+5);
  rejected:=false;begin perform public.asignar_grupo_equipos(company,gid,version,array[a,b],'Obra grupo A',hoy,hoy+5,false);exception when others then rejected:=true;end;
  if not rejected then raise exception 'Ignoró arriendo activo'; end if;
  delete from public.maquinaria_arriendos where id=-b;
  rejected:=false;begin perform public.asignar_grupo_equipos(company,gid,version,array[a],'Obra grupo A',hoy,hoy+5,false);exception when others then rejected:=true;end;
  if not rejected then raise exception 'Aceptó composición obsoleta'; end if;
  result:=public.asignar_grupo_equipos(company,gid,version,array[b,a],'Obra grupo A',hoy,hoy+5,false);
  if (result->>'asignados')::integer<>2 or (select count(*) from public.inventario_maquinaria where id in(a,b) and obra_nombre='Obra grupo A')<>2 then raise exception 'No asignó grupo completo'; end if;
  select actualizado_en into version from public.maquinaria_grupos where id=gid;
  rejected:=false;begin perform public.asignar_grupo_equipos(company,gid,version,array[a,b],'Obra grupo B',hoy,hoy+5,false);exception when others then rejected:=true;end;
  if not rejected then raise exception 'Trasladó sin confirmación'; end if;
  perform public.asignar_grupo_equipos(company,gid,version,array[a,b],'Obra grupo B',hoy,hoy+5,true);
  select actualizado_en into version from public.maquinaria_grupos where id=gid;
  perform public.gestionar_grupo_equipos(company,'eliminar',gid,null,'','{}',version);
  if (select count(*) from public.inventario_maquinaria where id in(a,b) and obra_nombre='Obra grupo B')<>2 then raise exception 'Eliminar grupo alteró equipos'; end if;
  perform public.gestionar_grupo_equipos(company,'crear',null,'Grupo lectura','',array[a]);
  if has_table_privilege('authenticated','public.maquinaria_grupos','INSERT') or has_table_privilege('anon','public.maquinaria_grupos','SELECT') or has_function_privilege('anon','public.asignar_grupo_equipos(text,bigint,timestamptz,integer[],text,date,date,boolean)','EXECUTE') then raise exception 'Permisos excesivos'; end if;
  select auth_user_id into regular_actor from public.usuarios where empresa<>'Obraxis' and auth_user_id is not null and lower(coalesce(rol_base,rol,'')) not in ('superusuario','superadmin') limit 1;
  if regular_actor is null then raise exception 'Falta actor de otra empresa'; end if;
  perform set_config('request.jwt.claim.sub',regular_actor::text,true);
  rejected:=false;begin perform public.gestionar_grupo_equipos(company,'crear',null,'Intruso','',array[a]);exception when others then rejected:=true;end;
  if not rejected then raise exception 'Escritura entre empresas'; end if;
end; $$;
set local role authenticated;
do $$ begin
  if exists(select 1 from public.maquinaria_grupos where empresa='__TEST_GRUPOS_ROLLBACK__') or exists(select 1 from public.maquinaria_grupos_equipos where empresa='__TEST_GRUPOS_ROLLBACK__') then raise exception 'RLS no aísla empresas'; end if;
end; $$;
reset role;
rollback;
select 'OK: grupos, pertenencia, asignación atómica, conflictos, traslado, eliminación y RLS; prueba revertida' as resultado;
